/**
 * The parity fixtures, generated by scripts/generate_fixtures.py from the
 * reference. Read with JSON.parse rather than imported, so the compiler does
 * not infer a literal type for 190 kB of numbers.
 */
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

export interface ParityCase {
  name: string;
  width: number;
  height: number;
  focal: number;
  vanishingPoint: [number, number, number];
  strength: number;
  paniniD: number;
  compression: number;
  margin: number;
  pitchDeg: number;
  rollDeg: number;
  rotationFull: number[];
  rotation: number[];
  framing: {
    xMin: number;
    yMin: number;
    xMax: number;
    yMax: number;
    width: number;
    height: number;
  };
  /** [output x, output y, source u, source v]; u = v = -1 behind the camera. */
  samples: Array<[number, number, number, number]>;
  validCount: number;
  /** "free", or a proportion as Python's repr: [x, y, width, height]. */
  crops: Record<string, [number, number, number, number]>;
}

export interface PaniniPairs {
  d: number;
  rays: Array<[number, number, number]>;
  plane: Array<[number, number]>;
  back: Array<[number, number, number]>;
}

export interface Fixtures {
  referenceSha256: string;
  numpy: string;
  opencv: string;
  cases: ParityCase[];
  panini: PaniniPairs[];
}

export const fixtures = JSON.parse(
  readFileSync(join(import.meta.dirname, '../fixtures/parity.json'), 'utf8'),
) as Fixtures;

/** The largest absolute difference between two lists of numbers. */
export function maxDiff(a: readonly number[], b: readonly number[]): number {
  if (a.length !== b.length) return Infinity;
  return Math.max(...a.map((x, i) => Math.abs(x - b[i])));
}
